P_{\text{out}} &= h\nu_g \int_{\nu_g}^{\infty} n_\gamma(\nu) \, d\nu \\[4pt]
&= h\nu_g \, A \frac{R_\odot^2}{d_\odot^2} \frac{2\pi}{c^2} \int_{\nu_g}^{\infty} \nu^2 \exp\left(-\frac{h\nu}{k_B T_s}\right) d\nu \\[4pt]
&= k_B T_s x_g \, A \frac{R_\odot^2}{d_\odot^2} \frac{2\pi}{c^2} \left(\frac{k_B T_s}{h}\right)^3 \int_{x_g}^{\infty} x^2 e^{-x} \, dx \\[4pt]
&= \frac{2\pi k_B^4}{c^2 h^3} T_s^4 \, A \frac{R_\odot^2}{d_\odot^2} \, x_g \left(x_g^2 + 2x_g + 2\right) e^{-x_g}.
\end{aligned}
$$

